reach      TR-AUDIT-CREDIT sym=src/por/audit.rs::audit_credit_decision from=src/por/auditor.rs::run_audit_job   # ParVaultPorAudit guard audit-credit
reach      TR-VERDICT-CLASSES sym=src/por/audit.rs::chunk_audit_decision from=src/por/auditor.rs::run_audit_job   # ParVaultPorAudit guard verdict-classes
reach      TR-CHUNK-STORER sym=src/por/verifier.rs::por_storer_decision from=src/network/wire_handler.rs::handle_mesh_wire_request   # ParVaultPorAudit guard chunk-storer
