# --- v0.5.6 track A: edge TLS, read-only WebDAV over TLS (B-1 P1-P3, L-81, A-TLS 1-9) -----------
# The daemon serves TLS on every non-loopback edge bind (the certificate is made at the first such
# `up`, glue G-11), so the plain-HTTP refusal is reachable only from the plugins, which load PEM
# (A-TLS-3): B1-PLAIN is declared on parvault-fuse (`webdav --listen 0.0.0.0` without --tls-pem).
# The daemon side is covered by its TLS accept test, edge_daemon_tls (glue/tests, on integ). The
# key, pair and Host claims run on parvault-fuse, which serves the same edge code
# (`spawn_webdav_server_served`).
claim      B1-PLAIN-FUSE sym=src/http_edge.rs::edge_transport_decision accept=trust_enforcement_edge::b1_fuse_tls_nonloopback_serves reject=trust_enforcement_edge::b1_fuse_plain_nonloopback_refused code=reject.edge_plain_http_nonloopback bin=parvault-fuse
claim      B1-KEY    sym=src/http_edge.rs::tls_key_file_decision accept=trust_enforcement_edge::b1_tls_owner_only_pair_served reject=trust_enforcement_edge::b1_key_group_readable_refused code=reject.tls_key_mode bin=parvault-fuse
claim      B1-PAIR   sym=src/http_edge.rs::tls_key_pair_decision accept=trust_enforcement_edge::b1_tls_owner_only_pair_served reject=trust_enforcement_edge::b1_pair_mismatch_refused code=reject.tls_key_cert_mismatch bin=parvault-fuse
claim      WEBDAV-HOST sym=src/webdav.rs::serve_webdav_request accept=trust_enforcement_edge::b1_tls_owner_only_pair_served reject=trust_enforcement_edge::webdav_host_outside_sans_refused code=reject.webdav_host_mismatch bin=parvault-fuse   # A-TLS-7 on the TLS edge
claim      WEBDAV-PATH sym=src/webdav.rs::webdav_path_segments accept=trust_enforcement_edge::webdav_encoded_path_served reject=trust_enforcement_edge::webdav_traversal_paths_refused code=reject.webdav_path_invalid bin=parvault-fuse   # one decode, normalized segments only (Lead security condition)
claim      EDGE-FRAMING sym=src/http_edge.rs::head_framing_decision accept=trust_enforcement_edge::edge_framing_crlf_served reject=trust_enforcement_edge::edge_framing_bare_lf_refused code=reject.edge_bare_lf bin=parvault   # request smuggling (QA of T0)
kani       B1-PLAIN-K sym=src/http_edge.rs::edge_transport_decision harness=proof_edge_transport_never_plain_off_loopback_without_opt_out cover=plain non-loopback refused
kani       B1-KEY-K  sym=src/http_edge.rs::tls_key_file_decision harness=proof_tls_key_file_owner_only cover=group or world bits refused
kani       B1-PAIR-K sym=src/http_edge.rs::tls_key_pair_decision harness=proof_tls_key_pair_must_match cover=mismatched pair refused
suite      S-E1      test=windows_equiv_acceptance::e1_windows_equivalent needs=cmd:curl   # v0.5.6 E1
artifact   A-TLS-DOCKER script=scripts/docker_stage_webdav_tls.sh bin=parvault suite=docker_acceptance_gate::docker_acceptance_gate   # stage 14-webdav-tls, called by the acceptance gate

